import csv,re,json,sys
MD='data/papers_test/md_llm/Kubiak_2009.md'
P='data/inference_test/results/opus-5-5_raw.csv'
H=next(csv.reader(open(P)))
L=open(MD).read().split('\n')
page=[];n=0
for l in L:
    if 'PAGE BREAK' in l: n+=1
    page.append(131+n)
SRC="kubiak, p. j. (2009). fire responses of bushland plants after the january 1994 wildfires in northern sydney. cunninghamia, 11(1), 131-165."
LCR,NL='Lane Cove River valley','Narrabeen Lagoon catchment area'
Q_LCR="The Lane Cove River valley is situated in the northern Sydney metropolitan area (lat 33° 45' S, long 151° 05' E), in the Central Coast botanical subdivision of NSW."
Q_NL="The Narrabeen Lagoon catchment area is about 15 km northeast of the Lane Cove River catchment area and is about 8 km closer to the coast."
Q_FIRE="In early January 1994 wildfires burned areas of bushland in northern Sydney (lat 33° 45' S, long 151° 05' E) in coastal south-eastern Australia."
Q_SEV="The January 1994 fires in the Lane Cove River and Narrabeen Lagoon areas were generally of an apparently high intensity"
for q in (Q_LCR,Q_NL,Q_FIRE,Q_SEV): assert q in open(MD).read(), q
PAPER_NOTE=("fire_season_categorical derived from fire dates 6-8 january 1994 (lane cove river) and 8 january 1994 (narrabeen lagoon); "
 "fire severity printed 'apparently high intensity' (both areas) and 'very high intensity' (lane cove river fire, nsw state coroner 1995), some patches burnt at low or moderate intensity or unburnt; "
 "fire responses after 100% leaf scorch; observations lcr mainly jan 1994-oct 1999, nl mar-oct 1994; "
 "appendix 1 time columns are not split by site; "
 "appendix 1 abbreviations: w = weeks; y = year(s); c. = approximately; grn. = green fruit; imm. = immature fruit; ri. = ripe fruit; (shd) = shedding seed or spores; m.i.f. = moderate intensity fire; (1) = one plant; buds = flowers in bud; adv = advanced seedlings; prob. = probably; flowering time in bold = sizable proportion of population flowering; time underlined and bridging the resp and seed columns = unclear whether plants grew from seed or resprouted; "
 "primary juvenile period defined in the paper as the time taken by plants to flower after germination from seed, secondary juvenile period as the time for resprouting plants to flower after fire (p. 131); juvenile periods in appendix 1 often refer to fruiting or seed shedding as printed")
DEF={'R':'majority of adult plants resprouted after the fires','K':'majority of adult plants killed by the fires',
 'r':'a small proportion of adult plants of this species resprouted after the fires','k':'a small proportion of adult plants of this species were killed by the fires',
 'pR':'probably resprouted after the fires','pK':'probably killed by the fires','?R':'possibly resprouted','?K':'possibly killed'}
PROB="'probably' = say 80–90% sure of observation"; POSS="'possibly' = say 50–70% sure of observation"
def fr(code):
    """return (value, note)"""
    c=code.replace('? ','?')
    simple={'R':'resprouter','K':'obligate','pR':'resprouter','pK':'obligate','?R':'resprouter','?K':'obligate',
            'K/r':'O/r','R/k':'R/o','R/K':'O/R','K/R':'O/R','?K/r':'O/r','pK/r':'O/r','R/?k':'R/o'}
    if c in simple:
        parts=re.split(r'/',c)
        d=[]
        for p in parts:
            base=p.lstrip('p?')
            dd=DEF[base]
            if p.startswith('p'): dd='probably '+dd if p!='pR' and p!='pK' else DEF[p]
            if p.startswith('?'): dd='possibly '+dd if p not in('?R','?K') else DEF[p]
            d.append(f"'{p}' = {dd}")
        note=f"fire response code printed '{code}' = "+'; '.join(d) if '/' in c else f"fire response code '{c}' = {DEF[c]}"
        if '/' in c: note=f"fire response code printed '{code}': "+'; '.join(d)
        cert=[]
        if 'p' in c: cert.append(PROB)
        if '?' in c: cert.append(POSS)
        if cert: note+='; certainty as stated in the paper: '+'; '.join(cert)
        if c in('R/K','K/R'): note+='; combined code not defined in the paper, read as killed and resprouting in similar proportions'
        return simple[c],note
    if c in('k/r','k','?k','?r'):
        d='; '.join(f"'{p}' = "+('possibly ' if p.startswith('?') else '')+DEF[p.lstrip('?')] for p in c.split('/'))
        return '',f"fire response code printed '{code}': {d}; no clear class"
    if c.startswith('K;r'):
        return '',f"fire response codes printed '{code}': 'K' = {DEF['K']}; 'r' = {DEF['r']}, after a moderate intensity fire (m.i.f.), with 71w; conflicting codes"
    if c.startswith('R(1)'):
        return '',f"fire response printed '{code}': one plant resprouted after a low to moderate intensity fire, host canopy not 100% scorched; code 'R' = {DEF['R']}; no clear class"
    raise ValueError(code)
TOK=re.compile(r'(\d+(?:\.\d+)?)(?:\s?–\s?(\d+(?:\.\d+)?))?(\+)?\s?(w|y)?')
def tval(raw):
    """parse time cell -> (value or '', is_text)"""
    s=raw.replace('**','').strip()
    if s.startswith('Less than 1 year'): return '<1 years'
    if s.startswith('At least 5 years'): return '>5 years'
    s2=re.sub(r'^\??c\.\s?\??','',s).lstrip('?')
    if not re.match(r'\d',s2): return None
    toks=[m for m in TOK.finditer(s2) if m.group(1)]
    m=toks[0]; unit=m.group(4)
    if not unit:
        for t in toks[1:]:
            if t.group(4): unit=t.group(4); break
    v=m.group(1)+('–'+m.group(2) if m.group(2) else '')
    if m.group(3): v='>'+v
    return f"{v} {'weeks' if unit=='w' else 'years'}"
COLN={3:'seedlings first observed',4:'first flowering of resprouts',5:'first flowering from seed',6:'first fruiting of resprouts',7:'first fruiting from seed',8:'primary juvenile period',9:'secondary juvenile period'}
TCOL={4:'time_to_first_flower_production_resprout_repr3a',5:'age_at_first_flower_production_from_seed_repr3',8:'primary_juvenile_period',9:'secondary_juvenile_period'}
rows=[]; fam=''; nsp=0; log=[]
start=next(i for i,l in enumerate(L) if l.startswith('**Appendix 1.'))
for i in range(start,len(L)):
    l=L[i]
    if not l.startswith('|') or l.startswith('|---') or 'Family/Species' in l: continue
    c=[x.strip() for x in l.strip().strip('|').split('|')]
    m=re.fullmatch(r'\*\*(.+?)\*\*',c[0])
    if m and all(x=='' for x in c[1:]):
        if m.group(1).endswith('aceae'): fam=m.group(1)
        continue
    nsp+=1
    name=re.sub(r'\s+',' ',c[0]); nnotes=[]; ns=''
    if name.startswith('(*?)'): name=name[4:]; nnotes.append("printed with '(*?)' before the name (exotic status uncertain)")
    elif name.startswith('*'): name=name[1:]; ns='exotic'
    pk=re.search(r'\((prob|poss)\.pk\.pf\.(?:fi\.)?(flower|fruit)\.(.+?)\)',name)
    if pk:
        nnotes.append(f"{'probable' if pk.group(1)=='prob' else 'possible'} peak of post-fire {'flowering' if pk.group(2)=='flower' else 'fruiting'} {pk.group(3)} (printed '{pk.group(0)[1:-1]}')")
        name=name.replace(pk.group(0),'').strip()
    for tag in re.findall(r'\((s\.lat\.|s\.str\.|syn\. [^)]+)\)',name):
        nnotes.append(f"name printed with '({tag})'"); name=name.replace(f'({tag})','').strip()
    printed=name
    w=name.split(' ')
    genus=w[0]; species=''; subsp=''
    rest=w[1:]
    if rest and rest[0] in ('sp.','species','hybrid','?(hybrid)'):
        nnotes.append(f"species not named: printed '{printed}'"); rest=[]
    elif rest and rest[0] in ('x','X'):
        species=rest[1]; nnotes.append(f"hybrid: name printed '{printed}'"); rest=rest[2:]
    elif rest:
        species=rest[0]; rest=rest[1:]
    if rest:
        rk=rest[0]; subsp=(rk if rk!='cv.' else 'cv.')+' '+' '.join(rest[1:])
    for part,lab in ((species,'species'),(subsp,'subsp')):
        if '?' in part or '“' in part:
            nnotes.append(f"name printed as '{printed}'")
    species=species.replace('?','').replace('“','').replace('”','')
    subsp=subsp.replace('?','')
    if '?' in genus: genus=genus.replace('?','')
    # site codes
    sites={}
    for j,s in ((1,LCR),(2,NL)):
        code=c[j]
        if not code: continue
        if code.startswith('The host'):
            nnotes.append(f"narrabeen lagoon fire response cell printed '{code}'"); continue
        sites[s]=fr(code)
    # times
    tv={}; tnotes=[]
    und45=('<u>' in c[4] or '<u>' in c[5]); und67=('<u>' in c[6] or '<u>' in c[7])
    for j in range(3,10):
        raw=re.sub(r'\s+',' ',c[j]); 
        if not raw: continue
        if j in(4,5) and und45:
            if j==4: tnotes.append(f"first flowering printed '{raw}' underlined across the resp and seed columns: unclear whether plants grew from seed or resprouted, not filled")
            continue
        if j in(6,7) and und67:
            if j==6: tnotes.append(f"first fruiting printed '{raw}' underlined across the resp and seed columns: unclear whether plants grew from seed or resprouted")
            continue
        if j in TCOL:
            v=tval(raw)
            if v:
                tv[TCOL[j]]=v
                if raw.replace('**','')!=v.split(' ')[0]+('w' if 'weeks' in v else 'y'):
                    tnotes.append(f"{TCOL[j]} printed '{raw}'")
            else:
                tnotes.append(f"{COLN[j]} cell printed '{raw}', not filled")
        else:
            tnotes.append(f"{COLN[j]} {raw} (near-match, not filled)" if j!=3 or re.match(r'[\d?]',raw) else f"seedlings first observed cell printed '{raw}'")
    pg=page[i]; q=re.sub(r'\s+',' ',l.strip())
    rows.append(dict(i=i,pg=pg,q=q,genus=genus,species=species,subsp=subsp,native_status=ns,family=fam,sites=sites,tv=tv,tnotes=tnotes,nnotes=nnotes,raw=c))
json.dump(rows,open(sys.argv[1],'w'),ensure_ascii=False)
print(nsp,len(rows))
