    code=d['Fire response']
    notes.append(f"fire response code{'s' if ' ' in code else ''} printed '{code}', not defined in the paper")
    if d['Synonym']: notes.append(f"synonym printed '{d['Synonym']}'")
    if d['Comments on regeneration']: notes.append(f"comments on regeneration printed '{d['Comments on regeneration']}'")
    uva=False
    for col,lab in (('Primary juvenile','primary juvenile period'),('Secondary juvenile period','secondary juvenile period')):
        if v[col]: notes.append(f"{lab} printed '{v[col]}', unit not stated"); uva=True
    ns=''
    if v['Distribution: NSW']=='Exotic': ns='exotic'; notes.append("native_status from distribution printed 'Exotic'"); uva=True
    notes.append(PW)
    fam=d['Family'].split(':')[0].strip()
    if ':' in d['Family']: notes.insert(0,f"family printed '{d['Family']}'")
    row={h:'' for h in H}
    dl=[f"table, pdf p. {d['_pg']}"]; dq=[f"[table, pdf p. {d['_pg']}] {d['_q']}"]
    if uva: dl.append(f"vital attributes: table, pdf p. {v['_pg']}"); dq.append(f"[vital attributes: table, pdf p. {v['_pg']}] {v['_q']}")
    row.update(genus=genus,species=species,subsp=subsp,native_status=ns,family=fam,fire_response_categorical_surv1=code,
               data_location='; '.join(dl),data_quote='; '.join(dq),notes='; '.join(notes),source=FN,file_name=FN)
    out.append(row)
w=csv.DictWriter(open(P,'a',newline=''),fieldnames=H,lineterminator='\n'); w.writerows(out)
print(len(out))
import random; random.seed(3)
for r in random.sample(out,3): print({k:v for k,v in r.items() if v and k not in('source','file_name')}); print()
